function todayTitle() {
  var now = new Date();
  var mm = String(now.getMonth() + 1);
  var dd = String(now.getDate());
  if (mm.length < 2) mm = '0' + mm;
  if (dd.length < 2) dd = '0' + dd;
  return 'Journal — ' + now.getFullYear() + '-' + mm + '-' + dd;
}

var btn = document.createElement('button');
btn.className = 'btn plugin-journal-btn';
btn.textContent = "Today's Entry";
btn.onclick = function() {
  var title = todayTitle();
  var existing = ctx.api.data.listCards().filter(function(c) { return c.title === title; });
  if (existing.length > 0) {
    ctx.api.ui.showToast('Today\'s entry already exists — search for "' + title + '"', 'info');
    return;
  }
  ctx.api.data.createCard({ title: title, body: '', tags: ['journal'] });
  ctx.api.ui.showToast('Created ' + title, 'success');
};
ctx.api.ui.inject('.header', btn, 'append');

ctx.logger.info('Daily journal ready');
